        case project = "project"
        case retrySeconds = "retry_seconds"
        case schemaTokens = "schema_tokens"
        case state = "state"
        case tools = "tools"
        case toolsHidden = "tools_hidden"
    }

    public init(approval: Approval?, command: String, config: String?, enabled: Bool?, error: String?, name: String, onDemand: Bool?, project: String?, retrySeconds: Double?, schemaTokens: Int?, state: AddedState, tools: [String]?, toolsHidden: Int?) {
