    public let detail: String?
    public let elapsedMS: Int?
    public let state: MCPTestProgressState
    public let step: Step
    public let testID: String

    public enum CodingKeys: String, CodingKey {
        case detail = "detail"
        case elapsedMS = "elapsed_ms"
        case state = "state"
        case step = "step"
        case testID = "test_id"
    }

    public init(detail: String?, elapsedMS: Int?, state: MCPTestProgressState, step: Step, testID: String) {
        self.detail = detail
