/// ``keychain:mcp/<name>``, never the secret itself.
// MARK: - MCPUpdateParamsConfig
public struct MCPUpdateParamsConfig: Codable {
    public let approval: Approval?
    public let args: [String]?
    public let autoEnable: Bool?
    public let command: String?
    public let cwd: String?
    public let enabled: EnabledUnion?
    public let env: [String: String]?
    public let envPassthrough: [String]?
    public let headers: [String: String]?
    public let oauth: AmbitiousMCPOAuthConfig?
    public let timeoutSeconds: Int?
    public let tools: AmbitiousMCPToolFilterConfig?
    public let url: String?

    public enum CodingKeys: String, CodingKey {
        case approval = "approval"
        case args = "args"
        case autoEnable = "auto_enable"
        case command = "command"
        case cwd = "cwd"
        case enabled = "enabled"
        case env = "env"
        case envPassthrough = "env_passthrough"
        case headers = "headers"
        case oauth = "oauth"
        case timeoutSeconds = "timeout_seconds"
        case tools = "tools"
        case url = "url"
    }

    public init(approval: Approval?, args: [String]?, autoEnable: Bool?, command: String?, cwd: String?, enabled: EnabledUnion?, env: [String: String]?, envPassthrough: [String]?, headers: [String: String]?, oauth: AmbitiousMCPOAuthConfig?, timeoutSeconds: Int?, tools: AmbitiousMCPToolFilterConfig?, url: String?) {
        self.approval = approval
        self.args = args
        self.autoEnable = autoEnable
        self.command = command
        self.cwd = cwd
        self.enabled = enabled
        self.env = env
        self.envPassthrough = envPassthrough
        self.headers = headers
        self.oauth = oauth
        self.timeoutSeconds = timeoutSeconds
        self.tools = tools
        self.url = url
    }
}

