/// One row of the option table: what an option may be, and what it does.
///
/// ``kind`` ``duration`` is a time such as ``5m``, or a number of seconds, and
/// ``-1`` for always. ``choice`` is one of ``values``, which are the values this
/// model takes, and has no range. ``default`` is Ollama's own, and ``None`` when
/// it has none, as for the seed and for ``think``.
// MARK: - ModelOption
public struct ModelOption: Codable {
    public let modelOptionDefault: Default?
    public let kind: ModelOptionKind
    public let label: String
    public let long: String
    public let maximum: Double?
    public let minimum: Double?
    public let name: String
    public let short: String
    public let step: Double?
    public let values: [String]?

    public enum CodingKeys: String, CodingKey {
        case modelOptionDefault = "default"
        case kind = "kind"
        case label = "label"
        case long = "long"
        case maximum = "maximum"
        case minimum = "minimum"
        case name = "name"
        case short = "short"
        case step = "step"
        case values = "values"
    }

    public init(modelOptionDefault: Default?, kind: ModelOptionKind, label: String, long: String, maximum: Double?, minimum: Double?, name: String, short: String, step: Double?, values: [String]?) {
        self.modelOptionDefault = modelOptionDefault
        self.kind = kind
        self.label = label
        self.long = long
        self.maximum = maximum
        self.minimum = minimum
        self.name = name
        self.short = short
        self.step = step
        self.values = values
    }
}

public enum ModelOptionKind: String, Codable {
    case choice = "choice"
    case duration = "duration"
    case float = "float"
    case int = "int"
}

public enum Default: Codable {
    case double(Double)
    case string(String)
    case null

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Double.self) {
            self = .double(x)
            return
        }
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        if container.decodeNil() {
            self = .null
            return
        }
        throw DecodingError.typeMismatch(Default.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for Default"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .double(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        case .null:
            try container.encodeNil()
        }
    }
}

