public enum Agent: Codable {
    case agentAgentSnapshot(AgentAgentSnapshot)
    case string(String)
    case null

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        if let x = try? container.decode(AgentAgentSnapshot.self) {
            self = .agentAgentSnapshot(x)
            return
        }
        if container.decodeNil() {
            self = .null
            return
        }
        throw DecodingError.typeMismatch(Agent.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for Agent"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .agentAgentSnapshot(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        case .null:
            try container.encodeNil()
        }
    }
}

/// The agent type a helper session started with, as its file read at that moment.
///
/// Editing the file later does not change it. ``source`` is where the file was
/// found. ``wish`` is the model wish as written. ``tools`` are the tool names the
/// helper may use, empty for none. ``asks`` is true when the helper may ask you a
/// question.
// MARK: - AgentAgentSnapshot
public struct AgentAgentSnapshot: Codable {
    public let asks: Bool?
    public let limits: IndigoAgentLimits?
    public let name: String
    public let source: Origin
    public let tools: [String]?
    public let wish: String

    public enum CodingKeys: String, CodingKey {
        case asks = "asks"
        case limits = "limits"
        case name = "name"
        case source = "source"
        case tools = "tools"
        case wish = "wish"
    }

    public init(asks: Bool?, limits: IndigoAgentLimits?, name: String, source: Origin, tools: [String]?, wish: String) {
        self.asks = asks
        self.limits = limits
        self.name = name
        self.source = source
        self.tools = tools
        self.wish = wish
    }
}

/// What bounds one helper of this type. ``None`` means the file sets no limit of that kind.
///
/// ``max_seconds`` is working time: it does not count the time spent waiting for
/// you, for a slot or for a provider. ``answer_chars`` cuts the helper's final answer.
// MARK: - IndigoAgentLimits
public struct IndigoAgentLimits: Codable {
    public let answerChars: Int?
    public let maxCalls: Int?
    public let maxCostUsd: Double?
    public let maxSeconds: Int?
    public let maxTokens: Int?

    public enum CodingKeys: String, CodingKey {
        case answerChars = "answer_chars"
        case maxCalls = "max_calls"
        case maxCostUsd = "max_cost_usd"
        case maxSeconds = "max_seconds"
        case maxTokens = "max_tokens"
    }

    public init(answerChars: Int?, maxCalls: Int?, maxCostUsd: Double?, maxSeconds: Int?, maxTokens: Int?) {
        self.answerChars = answerChars
        self.maxCalls = maxCalls
        self.maxCostUsd = maxCostUsd
        self.maxSeconds = maxSeconds
        self.maxTokens = maxTokens
    }
}

/// A tool allowed for the rest of a session. ``subject`` null allows every call of it.
// MARK: - PurpleSessionAllowance
public struct PurpleSessionAllowance: Codable {
    public let subject: String?
    public let tool: String

    public enum CodingKeys: String, CodingKey {
        case subject = "subject"
        case tool = "tool"
    }

    public init(subject: String?, tool: String) {
        self.subject = subject
        self.tool = tool
    }
}

/// The caps of ``[budget]`` and what is spent, in USD. A cap that is not set is null.
// MARK: - FluffyConsentCaps
public struct FluffyConsentCaps: Codable {
    public let dailyUsd: Double?
    public let sessionUsd: Double?
    public let spentSession: Double
    public let spentToday: Double

    public enum CodingKeys: String, CodingKey {
        case dailyUsd = "daily_usd"
        case sessionUsd = "session_usd"
        case spentSession = "spent_session"
        case spentToday = "spent_today"
    }

    public init(dailyUsd: Double?, sessionUsd: Double?, spentSession: Double, spentToday: Double) {
        self.dailyUsd = dailyUsd
        self.sessionUsd = sessionUsd
        self.spentSession = spentSession
        self.spentToday = spentToday
    }
}

public enum ChecksUnion: Codable {
    case checkElementArray([CheckElement])
    case enumeration(ChecksEnum)
    case null

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode([CheckElement].self) {
            self = .checkElementArray(x)
            return
        }
        if let x = try? container.decode(ChecksEnum.self) {
            self = .enumeration(x)
            return
        }
        if container.decodeNil() {
            self = .null
            return
        }
        throw DecodingError.typeMismatch(ChecksUnion.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for ChecksUnion"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .checkElementArray(let x):
            try container.encode(x)
        case .enumeration(let x):
            try container.encode(x)
        case .null:
            try container.encodeNil()
        }
    }
}

