        case modelProfile = "model_profile"
        case origin = "origin"
        case planFirst = "plan_first"
    }

    public init(branch: String?, createBranch: Bool?, cwd: String?, modelProfile: String?, origin: OriginEnum?, planFirst: Bool?) {
        self.branch = branch
        self.createBranch = createBranch
